-- composition of rule kernels common_aggregate x empty_result_pullup (duckdb), template cte_twice
WITH ka AS (WITH RECURSIVE rc(c0) AS (SELECT 1 UNION ALL SELECT r.c0 + 1 FROM rc AS r WHERE r.c0 < 5) SELECT FALSE AS c0, TRUE AS c1, ARRAY['1'::text] AS c2 UNION (SELECT FALSE AS c0, TRUE AS c1, []::text[] AS c2 FROM t4 AS a1 WHERE NULL::boolean EXCEPT (SELECT FALSE AS c0, FALSE AS c1, ARRAY['1'::text] AS c2 UNION SELECT TRUE AS c0, TRUE AS c1, ARRAY['1'::text] AS c2))), kb AS (SELECT '{"k": -1, "a": [1, 2, 3]}'::jsonb AS c0, 0.5::numeric AS c1, 1::bigint AS c2, 'a'::text AS c3 FROM t3 AS a1 HAVING BOOL_AND ((a1.c5 < ANY (SELECT 'NaN'::text AS c0)))) SELECT (SELECT count(*) FROM ka) + (SELECT count(*) FROM kb) + (SELECT count(*) FROM ka);
-- pgfuzz:check kernel:cte_twice SELECT 2 * (SELECT count(*) FROM (WITH RECURSIVE rc(c0) AS (SELECT 1 UNION ALL SELECT r.c0 + 1 FROM rc AS r WHERE r.c0 < 5) SELECT FALSE AS c0, TRUE AS c1, ARRAY['1'::text] AS c2 UNION (SELECT FALSE AS c0, TRUE AS c1, []::text[] AS c2 FROM t4 AS a1 WHERE NULL::boolean EXCEPT (SELECT FALSE AS c0, FALSE AS c1, ARRAY['1'::text] AS c2 UNION SELECT TRUE AS c0, TRUE AS c1, ARRAY['1'::text] AS c2))) AS ka) + (SELECT count(*) FROM (SELECT '{"k": -1, "a": [1, 2, 3]}'::jsonb AS c0, 0.5::numeric AS c1, 1::bigint AS c2, 'a'::text AS c3 FROM t3 AS a1 HAVING BOOL_AND ((a1.c5 < ANY (SELECT 'NaN'::text AS c0)))) AS kb)
